  function workflowText(data,metric,weekStart,field){return (data.weeklyNotes||[]).find(x=>x.week_start===weekStart&&x.metric_key===metric)?.[field]||'';}
  function issueEvidencePanels(issue,evidence,issueTitle='發現問題',evidenceTitle='提出證據'){return '<div class="analysis-grid workflow-issue-evidence"><section class="analysis-panel"><h3>'+issueTitle+'</h3><div class="workflow-copy">'+escape(issue)+'</div></section><section class="analysis-panel"><h3>'+evidenceTitle+'</h3><div class="workflow-copy">'+escape(evidence)+'</div></section></div>';}
  function comparisonValues(data,r,metric){const rows=storeAnalytics(data,r),summary=model(data,r).summary,total=key=>rows.reduce((n,x)=>n+(x[key]||0),0),tc=total('tc');if(metric==='sstg')return [['SSTG',summary.tc?summary.sstg:null,'rate'],['TC',summary.tc,'count']];if(metric==='d7'||metric==='d25'){const y7=total('d7Y'),n7=total('d7N'),y25=total('d25Y'),n25=total('d25N');return [['D7',y7+n7?y7/(y7+n7):null,'rate'],['D25',y25+n25?y25/(y25+n25):null,'rate']];}if(metric==='fa')return [['FA 佔比',summary.faShare,'rate'],['TPLH',summary.tplh,'decimal'],['TC',tc,'count']];if(metric==='waiting')return [['等餐筆數',data.delays.length,'count'],['等餐／TC',tc?data.delays.length/tc:null,'rate']];const fb=data.feedback||[];return [['0800 抱怨',fb.filter(x=>x.source_type==='0800').length,'count'],['4128 紀錄',fb.filter(x=>x.source_type==='4128').length,'count']];}
