  async function loadReport(force=false){const id=++state.request,r=range();renderChoices();document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period===state.period));$('report').classList.add('hidden');$('metricTabs').classList.add('hidden');$('refresh').disabled=true;status('讀取成績中…');try{const data=await loadRange(r,force);if(id!==state.request)return;state.data=data;const pr=previousRange(r,data),previous=await loadRange(pr,force);if(id!==state.request)return;state.comparisonRange=pr;state.previous=previous;try{await weatherForRange(r);}catch(e){}if(id!==state.request)return;status('');$('report').classList.remove('hidden');const rows=storeAnalytics(data,r);renderMetric(data,previous,r);$('export').onclick=()=>renderExport(data,rows,r);}catch(e){if(id===state.request)status('載入失敗：'+e.message,true);}finally{$('refresh').disabled=false;}}
  document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{const changed=state.period!==b.dataset.period;state.period=b.dataset.period;state.month=state.date.slice(0,7);if(changed)$('periodPicker').classList.remove('hidden');else $('periodPicker').classList.toggle('hidden');renderChoices();loadReport();});$('periodDate').onchange=()=>{state.date=$('periodDate').value||today();state.month=state.date.slice(0,7);renderChoices();loadReport();};$('periodPrev').onclick=()=>changePeriod(-1);$('periodNext').onclick=()=>changePeriod(1);$('refresh').onclick=()=>loadReport(true);
  (async()=>{try{const {data,error}=await db.auth.getSession();if(error)throw error;if(!data.session){$('authMessage').classList.remove('hidden');$('authMessage').innerHTML='請先登入營運後台，再開啟分析儀表板。<br><a href="admin.html">前往登入</a>';return;}state.date=today();state.month=state.date.slice(0,7);$('dashboard').classList.remove('hidden');await loadReport();}catch(e){$('authMessage').classList.remove('hidden');$('authMessage').textContent='登入狀態讀取失敗：'+e.message;}})();
